import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"IB","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/ib.md","filePath":"ideas/ib.md"}'),c={name:"ideas/ib.md"};function o(g,n,u,r,e,s){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="ib" tabindex="-1">IB <a class="header-anchor" href="#ib" aria-label="Permalink to &quot;IB&quot;">​</a></h1><p>Trên trang này# IB — International Baccalaureate <a href="#ib-—-international-baccalaureate">​</a> IB là một chương trình giáo dục quốc tế, không phải một phương pháp dạy học. Nó quy định học gì, đánh giá thế nào, và tốt nghiệp cần đạt gì — trong khi các mục khác trong nhóm này chỉ nói về <em>cách</em> dạy.</p><h2 id="bai-toan-ib-sinh-ra-đe-giai-​" tabindex="-1">Bài toán IB sinh ra để giải <a href="#bai-toan-ib-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-ib-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán IB sinh ra để giải [​](#bai-toan-ib-sinh-ra-đe-giai)&quot;">​</a></h2><p>Học sinh học nhiều môn rời rạc, giỏi làm bài thi, nhưng không nối được kiến thức giữa các môn, không tự đặt câu hỏi, và không viết nổi một bài dài có lập luận riêng. Câu trả lời của IB: bắt buộc học rộng, bắt buộc viết một tiểu luận nghiên cứu dài, bắt buộc học một môn về chính cách con người biết được điều mình biết, và bắt buộc tham gia hoạt động ngoài học thuật.</p><h2 id="cau-truc-​" tabindex="-1">Cấu trúc <a href="#cau-truc">​</a> <a class="header-anchor" href="#cau-truc-​" aria-label="Permalink to &quot;Cấu trúc [​](#cau-truc)&quot;">​</a></h2><p>IB có ba cấp: PYP (tiểu học), MYP (trung học cơ sở), và DP (hai năm cuối, nổi tiếng nhất). Ở DP, học sinh học <strong>sáu môn</strong> từ sáu nhóm khác nhau — ngôn ngữ mẹ đẻ, ngoại ngữ, xã hội, khoa học, toán, nghệ thuật hoặc môn thứ hai. Ba môn ở mức cao, ba môn mức chuẩn. Không được bỏ toán, không được bỏ ngoại ngữ. Cộng thêm ba phần bắt buộc:</p><ul><li><strong>Extended Essay</strong> — tiểu luận nghiên cứu 4.000 từ về một đề tài tự chọn.</li><li><strong>Theory of Knowledge</strong> — môn học về việc &quot;làm sao ta biết điều ta biết là đúng&quot;.</li><li><strong>CAS</strong> — hoạt động sáng tạo, thể chất và phục vụ cộng đồng.</li></ul><h2 id="manh-o-đau-​" tabindex="-1">Mạnh ở đâu <a href="#manh-o-đau">​</a> <a class="header-anchor" href="#manh-o-đau-​" aria-label="Permalink to &quot;Mạnh ở đâu [​](#manh-o-đau)&quot;">​</a></h2><p><strong>Không cho phép bỏ môn.</strong> Học sinh giỏi Toán vẫn phải viết luận; học sinh giỏi Văn vẫn phải học Toán. Điều này ngăn việc chuyên môn hoá quá sớm — thứ mà rất nhiều người sau này hối tiếc. <strong>Extended Essay là kinh nghiệm hiếm có.</strong> Tự chọn đề tài, tự tìm tài liệu, tự lập luận, viết 4.000 từ, chịu phản biện. Rất ít chương trình phổ thông nào bắt học sinh làm việc này, và nó là thứ gần nhất với công việc học thuật thật. <strong>Theory of Knowledge dạy thứ ít nơi dạy.</strong> Một môn học dành riêng cho câu hỏi &quot;bằng chứng nào đủ để tin điều gì đó&quot; là hiếm ở bậc phổ thông — và hữu ích suốt đời. <strong>Được công nhận rộng.</strong> Đại học ở nhiều nước hiểu và đánh giá cao IB.</p><h2 id="yeu-o-đau-​" tabindex="-1">Yếu ở đâu <a href="#yeu-o-đau">​</a> <a class="header-anchor" href="#yeu-o-đau-​" aria-label="Permalink to &quot;Yếu ở đâu [​](#yeu-o-đau)&quot;">​</a></h2><p><strong>Khối lượng rất nặng.</strong> Sáu môn cộng ba phần bắt buộc là gánh lớn. Học sinh IB thường xuyên thiếu ngủ, và tỷ lệ căng thẳng cao là vấn đề được ghi nhận rộng rãi. <strong>Rộng đổi lấy sâu.</strong> Học sinh muốn đào rất sâu một lĩnh vực sẽ thấy IB phân tán. So với việc chuyên vào ba môn, IB dàn nguồn lực ra sáu. <strong>Không tối ưu cho các kỳ thi hẹp.</strong> Nếu mục tiêu là một kỳ thi chuyên toán hoặc một kỳ thi chuẩn hoá cụ thể, IB không phải con đường hiệu quả nhất — nó không được thiết kế cho việc đó. <strong>Chi phí và khả năng tiếp cận.</strong> Trường IB thường đắt, và không phải nơi nào cũng có. <strong>Chất lượng dao động mạnh theo trường.</strong> &quot;Trường IB&quot; là một cái nhãn. Trải nghiệm thực tế phụ thuộc vào giáo viên nhiều hơn phụ thuộc vào chương trình.</p><h2 id="ai-hop-ai-khong-​" tabindex="-1">Ai hợp, ai không <a href="#ai-hop-ai-khong">​</a> <a class="header-anchor" href="#ai-hop-ai-khong-​" aria-label="Permalink to &quot;Ai hợp, ai không [​](#ai-hop-ai-khong)&quot;">​</a></h2><p>Cân nhắc kỹ nếuCon đã xác định rõ một hướng hẹp và muốn đào sâu · Con đang chuẩn bị cho một kỳ thi chuyên biệt · Con dễ quá tải và cần nhịp vừa phải · Gia đình không đủ điều kiện duy trì tới hết chương trình Phù hợp nếuCon học đều và tò mò nhiều lĩnh vực · Gia đình nhắm du học · Con viết được và chịu được khối lượng · Bạn coi trọng chiều rộng hơn thứ hạng ở một môn</p><h2 id="đieu-thuong-bi-hieu-nham-​" tabindex="-1">Điều thường bị hiểu nhầm <a href="#đieu-thuong-bi-hieu-nham">​</a> <a class="header-anchor" href="#đieu-thuong-bi-hieu-nham-​" aria-label="Permalink to &quot;Điều thường bị hiểu nhầm [​](#đieu-thuong-bi-hieu-nham)&quot;">​</a></h2><p><strong>&quot;IB là nhẹ nhàng, không áp lực.&quot;</strong> Ngược lại — IB thường nặng hơn chương trình phổ thông thường. Cái khác là áp lực đến từ khối lượng và chiều rộng, không phải từ luyện đề. <strong>&quot;Học IB thì không cần học thuộc.&quot;</strong> Vẫn cần. IB đòi hỏi nền kiến thức vững; nó chỉ không dừng lại ở đó. <strong>&quot;Vào trường IB là con sẽ tư duy phản biện.&quot;</strong> Cái nhãn không tạo ra điều đó. Giáo viên tạo ra điều đó. IB giải bài toán &quot;biết nhiều nhưng rời rạc và thụ động&quot;. Nếu con bạn không có bài toán đó, IB có thể là một cái giá đắt cho thứ bạn không cần. <a href="/ideas/aops">AoPS →</a></p>',15)])])}const b=h(c,[["render",o]]);export{m as __pageData,b as default};
